"""Original N2-MOCK-08 listening scripts about education and technology."""

def _opts(texts):
    return [{"id": chr(65+i), "text": text} for i,text in enumerate(texts)]


def _q(qid, type_id, category, script, stem, options, key, explanation):
    return {
        "id": qid, "typeId": type_id, "category": category,
        "script": script, "stem": stem, "options": _opts(options),
        "correctAnswer": key, "explanation": explanation,
    }


