    # Replace the weak Mondai 4 distractors with plausible, situation-related
    # responses while preserving each authored correct response and key.
    m4_revisions = {
        "N2_08_M4_L01": (["その図は、発表の最後に載せると見やすいですよ。", "図の説明は、口頭でも補ってください。"], ["配置の助言には答えず、出典を示せば利用できるかという許可条件にも触れていません。", "説明方法の助言だけで、図を使ってよいかという許可には答えていません。"]),
        "N2_08_M4_L02": (["資料の該当ページを、あとで送りますね。", "次の授業の質問時間に、まとめて聞いてください。"], ["資料を送る申し出だけでは、説明のどの部分が分からないかという話に応じていません。", "質問の機会を案内するだけで、今の理解の難しさに直接応じていません。"]),
        "N2_08_M4_L03": (["使った時間を、記録簿に記入しておいてください。", "装置の点検日は、扉の内側に書いてあります。"], ["使用記録の指示であり、使用後に電源を切るかという確認への返答ではありません。", "点検日の案内であり、使用後の電源の扱いを示していません。"]),
        "N2_08_M4_L04": (["では、私はスライドの順番を確認しておきます。", "図の出典は、資料の最後にまとめてください。"], ["別の準備作業を申し出ていますが、図の説明を担当してよいかへの返答ではありません。", "出典の記載方法を指示していますが、担当の申し出への返答ではありません。"]),
        "N2_08_M4_L05": (["論文の要点は、ゼミで説明してください。", "読んだ箇所には、付箋を貼っておいてください。"], ["発表の指示であり、ゼミまでに読む範囲を尋ねた質問への答えではありません。", "読み方の助言だけで、論文全体を読む必要があるかに答えていません。"]),
        "N2_08_M4_L06": (["利用可能な時間帯は、図書館のサイトに載っています。", "データベースの利用申請は、学期ごとに更新してください。"], ["利用時間の案内では、学外から接続できない問題を解決できません。", "申請の更新案内であり、現在のログイン状態を確かめる助言ではありません。"]),
        "N2_08_M4_L07": (["発表時間は一人十分です。", "順番が決まったら、資料を共有フォルダに置いてください。"], ["持ち時間の案内だけでは、発表順を今決める提案への返答になりません。", "資料共有の指示で、順番の決め方を提案していません。"]),
        "N2_08_M4_L08": (["凡例には、各線が何を示すかも書いてください。", "目盛りの間隔をそろえると見やすくなります。"], ["凡例への助言ですが、単位を明記する利点について答えていません。", "目盛りについての助言で、単位の表示を確認した質問への返答ではありません。"]),
        "N2_08_M4_L09": (["申請書の提出先は、教務課の窓口です。", "添付書類はPDF形式で提出してください。"], ["提出先の案内だけでは、締切が明日で未申請という状況への助言になりません。", "提出形式の指示で、まず必要書類を急いでそろえる助言ではありません。"]),
        "N2_08_M4_L10": (["専門用語を使うこと自体は、発表では大切です。", "用語の意味は、質問があればその場で説明します。"], ["用語使用の是非に触れるだけで、説明を分かりやすく直す提案をしていません。", "質問後に説明する方針で、現在の説明を直す提案にはなっていません。"]),
        "N2_08_M4_L11": (["予想した結果になるまで、測定を続けてみましょう。", "予想と異なる数値は、発表資料から外しておきましょう。"], ["予想に合わせて測定を続ける提案で、条件や手順を確かめる返答ではありません。", "異なる結果を隠す提案であり、結果の原因を確認する姿勢と異なります。"]),
    }
    for item in q:
        if item["id"] in m4_revisions:
            replacement_texts, replacement_reasons = m4_revisions[item["id"]]
            wrong = [option for option in item["options"] if option["id"] != item["correctAnswer"]]
            for option, replacement in zip(wrong, replacement_texts):
                option["text"] = replacement
            distractor_reasons[item["id"]] = replacement_reasons

    for item in q:
        old_key = item["correctAnswer"]
        wrong_letters = [option["id"] for option in item["options"] if option["id"] != old_key]
        reasons = distractor_reasons[item["id"]]
        if len(wrong_letters) != len(reasons):
            raise ValueError(f"Distractor rationale count mismatch for {item['id']}")
        item["distractorExplanations"] = dict(zip(wrong_letters, reasons))

    # Balance answer positions within each listening Mondai by option movement
    # only; the authored answer text and its evidence remain unchanged.
    for type_id in ("N2-LIS-TASK","N2-LIS-POINT","N2-LIS-SUMM","N2-LIS-RESP","N2-LIS-INTEG"):
        group = [item for item in q if item["typeId"] == type_id]
        letters = ["A","B","C"] if type_id == "N2-LIS-RESP" else ["A","B","C","D"]
        counts = {letter: 0 for letter in letters}
        for item in group:
            old_key = item["correctAnswer"]
            target = min(letters, key=lambda letter: (counts[letter], letters.index(letter)))
            reasons_by_text = {
                option["text"]: item["distractorExplanations"][option["id"]]
                for option in item["options"] if option["id"] in item["distractorExplanations"]
            }
            correct_text = next(option["text"] for option in item["options"] if option["id"] == old_key)
            current_index = next(i for i, option in enumerate(item["options"]) if option["id"] == old_key)
            target_index = letters.index(target)
            item["options"][current_index], item["options"][target_index] = item["options"][target_index], item["options"][current_index]
            for index, option in enumerate(item["options"]):
                option["id"] = letters[index]
            item["correctAnswer"] = target
            item["distractorExplanations"] = {
                option["id"]: reasons_by_text[option["text"]]
                for option in item["options"] if option["text"] != correct_text
            }
            counts[target] += 1

    assert len(q) == 30
    assert [sum(x["typeId"] == t for x in q) for t in ("N2-LIS-TASK","N2-LIS-POINT","N2-LIS-SUMM","N2-LIS-RESP","N2-LIS-INTEG")] == [5,6,5,11,3]
    assert all(len(x["options"]) == (3 if x["typeId"] == "N2-LIS-RESP" else 4) for x in q)
    return q
